      const res = await fetch("/api/front-desk/desk", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "bootstrap" }) });
      if (!res.ok) { const data = await res.json() as { error?: string }; throw new Error(data.error || "Couldn't initialize the workspace."); }
      let saved = "truly"; try { saved = localStorage.getItem("truly-workspace") === "practice" ? "practice" : "truly"; } catch {}
      const params = new URLSearchParams(location.search);
